 function dueSteps(enrs){var rows=[];enrs.forEach(function(e){if(e.status!=='Active')return;e.steps.forEach(function(s){if(s.status==='Open')rows.push(s)})});rows.forEach(function(s){s.timeState=!s.dueAt?'Unscheduled':day(s.dueAt)<day(now())?'Overdue':iso(s.dueAt)===iso(now())?'Today':days(now(),s.dueAt)<=7?'Next 7 Days':'Upcoming'});return rows.sort(function(a,b){return(a.dueAt?a.dueAt.getTime():Infinity)-(b.dueAt?b.dueAt.getTime():Infinity)})}
