 function completeForm(e,s){return'<div class="oc3-modal-wrap" onclick="if(event.target===this)_rp2OutreachCloseModal()"><aside class="oc3-modal"><div class="oc3-modal-head"><div><div class="oc3-modal-icon">'+icon(s.step.type)+'</div><div class="oc3-modal-kick">Complete sequence step</div><div class="oc3-modal-title">'+esc(s.step.title)+'</div><div class="oc3-modal-sub">'+esc((e.company||e.contactName||'Enrollment')+' · '+s.step.type+' · Due '+fmt(s.dueAt))+'</div></div><button class="oc3-close" onclick="_rp2OutreachCloseModal()">×</button></div><div class="oc3-detail"><div class="oc3-detail-label">Instructions and script</div><div class="oc3-detail-value">'+esc(s.step.instructions||'No instructions')+(s.step.script?'\n\n'+esc(s.step.script):'')+'</div></div><div class="oc3-form">'+fieldHtml('Completed date and time','oc3-x-date',localDateTime(now()),'datetime-local')+fieldHtml('Actual outcome','oc3-x-outcome','','select',[{value:'',label:'Choose actual outcome'}].concat(OUTCOMES))+fieldHtml('Activity note','oc3-x-note','','textarea')+fieldHtml('Next-touch date','oc3-x-next','','datetime-local')+fieldHtml('Next action','oc3-x-nextaction','','textarea')+'</div><div class="oc3-disclosure"><strong>Honest completion:</strong> Email Sent means it was actually sent; Connected means the customer actually engaged; Meeting Scheduled means a meeting was actually set.</div><div class="oc3-modal-actions"><button class="oc3-btn" onclick="_rp2OutreachCloseModal()">Cancel</button><button class="oc3-btn primary" onclick="_rp2OutreachSaveCompletion(\''+encodeURIComponent(e.id)+'\',\''+encodeURIComponent(s.id)+'\')">Complete step</button></div></aside></div>'}
 function modalHtml(g){var m=window._rp2OutreachModal;if(!m)return'';if(m.mode==='newCampaign')return campaignForm(g,null);if(m.mode==='newSequence')return sequenceForm(null);if(m.mode==='enroll')return audienceForm(g,m.campaignId?decodeURIComponent(m.campaignId):'');var c=m.id?campBy(decodeURIComponent(m.id),g.campaigns):null,s=m.id?seqBy(decodeURIComponent(m.id),g.sequences):null,e=m.id?g.enrollments.filter(function(x){return x.id===decodeURIComponent(m.id)})[0]:null;if(m.mode==='campaignDetail'&&c)return campaignDetail(g,c);if(m.mode==='editCampaign'&&c)return campaignForm(g,c);if(m.mode==='sequenceDetail'&&s)return sequenceDetail(s);if(m.mode==='editSequence'&&s)return sequenceForm(s);if(m.mode==='enrollmentDetail'&&e)return enrollmentDetail(e);if(m.mode==='complete'&&e){var st=e.steps.filter(function(x){return x.id===decodeURIComponent(m.stepId)})[0];if(st)return completeForm(e,st)}return''}
