 window._rp2OutreachNewSequence=function(){window._rp2OutreachStepDraft=[{id:id('step'),dayOffset:0,type:'Call',title:'First outreach step',instructions:'',script:'',required:true}];window._rp2OutreachModal={mode:'newSequence'};render()};window._rp2OutreachOpenSequence=function(x){window._rp2OutreachModal={mode:'sequenceDetail',id:x};render()};window._rp2OutreachEditSequence=function(x){var s=seqBy(decodeURIComponent(x),sequences());if(!s)return;window._rp2OutreachStepDraft=s.steps.map(function(st){return Object.assign({},st)});window._rp2OutreachModal={mode:'editSequence',id:x};render()};
