 window._rp2OutreachOpenEnrollment=function(x){window._rp2OutreachModal={mode:'enrollmentDetail',id:x};render()};window._rp2OutreachSetEnrollmentStatus=function(encoded,status){if(ENROLL_STATUS.indexOf(status)<0)return;var loc=enrollmentLoc(decodeURIComponent(encoded));if(loc.index<0)return;var old=loc.item.status;loc.item.status=status;loc.item.history=arr(loc.item.history);loc.item.history.push({type:'Enrollment status',copy:old+' → '+status,at:new Date().toISOString()});loc.bucket.data.enrollments[loc.index]=loc.item;saveStore(loc.bucket);audit('Enrollment status changed',loc.item.company||loc.item.contactName,old+' → '+status,loc.item.id);window._rp2OutreachModal=null;render()};
