 function updateLead(e,s,outcome,date,note,nextDate,nextAction){if(e.entityType!=='lead'||String(e.entityKey).indexOf('local|')!==0)return;var lid=String(e.entityKey).replace(/^local\|/,''),b=leadStore(),i=b.data.leads.findIndex(function(l){return l&&String(l.id)===lid});if(i<0)return;var l=b.data.leads[i];l.activities=arr(l.activities);l.activities.push({id:id('la'),type:s.step.type,date:date,subject:s.step.title,outcome:outcome,note:note,nextStep:nextAction,nextDate:nextDate,campaignId:e.campaignId,sequenceId:e.sequenceId});if(!l.firstResponseAt&&response(outcome))l.firstResponseAt=date;l.lastTouchAt=date;if(nextDate)l.nextTouchAt=nextDate;if(nextAction)l.nextStep=nextAction;if(outcome==='Qualified')l.status='Qualified';else if(outcome==='Not Now')l.status='Nurture';else if(['Not Interested','Wrong Contact','Do Not Contact'].indexOf(outcome)>=0)l.status='Disqualified';else if(['Connected','Interested','Meeting Scheduled'].indexOf(outcome)>=0&&['New','Assigned','Attempting Contact'].indexOf(clean(l.status))>=0)l.status='Connected';l.history=arr(l.history);l.history.push({type:'Sequence activity',copy:s.step.type+' · '+outcome,at:new Date().toISOString()});b.data.leads[i]=l;saveLeadStore(b)}
 function updateCrm(e,s,outcome,date,note,nextDate,nextAction){if(e.entityType!=='contact'&&e.entityType!=='company')return;var key=e.entityType==='contact'?String(e.entityKey).split('|')[0]:String(e.entityKey),b=repCrm(),a=b.data.accounts[key];if(!a)return;a.activities=arr(a.activities);a.activities.push({id:id('act'),source:'local',contactId:e.entityType==='contact'?String(e.entityKey).split('|').slice(1).join('|'):'',contactName:e.contactName,type:s.step.type,subject:s.step.title,detail:note,outcome:outcome,date:iso(date),nextStep:nextAction,nextDate:nextDate,campaignId:e.campaignId,sequenceId:e.sequenceId,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});if(e.entityType==='contact'){var cid=String(e.entityKey).split('|').slice(1).join('|'),i=arr(a.contacts).findIndex(function(c){return c&&String(c.id)===cid});if(i>=0){a.contacts[i].lastTouch=iso(date);if(nextDate)a.contacts[i].nextTouch=iso(nextDate);a.contacts[i].history=arr(a.contacts[i].history);a.contacts[i].history.push({type:'Sequence activity',copy:s.step.type+' · '+outcome,at:new Date().toISOString()})}}b.data.accounts[key]=a;b.store.reps[_rp2.rep]=b.data;localStorage.setItem(CRM_STORE,JSON.stringify(b.store))}
 window._rp2OutreachSaveCompletion=function(eidEncoded,sidEncoded){var eid=decodeURIComponent(eidEncoded),sid=decodeURIComponent(sidEncoded),g=build(),e=g.enrollments.filter(function(x){return x.id===eid})[0];if(!e)return;var s=e.steps.filter(function(x){return x.id===sid})[0],outcome=val('oc3-x-outcome');if(!s||s.status==='Completed'||!outcome)return;var completedAt=val('oc3-x-date')||new Date().toISOString(),note=val('oc3-x-note'),nextDate=val('oc3-x-next'),nextAction=val('oc3-x-nextaction'),loc=enrollmentLoc(eid);loc.item.stepState=loc.item.stepState||{};loc.item.stepState[sid]=Object.assign({},loc.item.stepState[sid]||{},{status:'Completed',completedAt:completedAt,outcome:outcome,note:note,nextDate:nextDate,nextAction:nextAction});loc.item.history=arr(loc.item.history);loc.item.history.push({type:'Step completed',copy:s.step.title+' · '+outcome,at:new Date().toISOString()});if(response(outcome)){loc.item.responseOutcome=outcome;loc.item.responseAt=completedAt;loc.item.status=positive(outcome)?'Responded':outcome==='Not Now'?'Paused':'Completed'}var remaining=e.steps.filter(function(x){return x.id!==sid&&x.status==='Open'}).length;if(!remaining&&!response(outcome))loc.item.status='Completed';loc.bucket.data.enrollments[loc.index]=loc.item;saveStore(loc.bucket);updateLead(e,s,outcome,completedAt,note,nextDate,nextAction);updateCrm(e,s,outcome,completedAt,note,nextDate,nextAction);audit('Sequence step completed',e.company||e.contactName,s.step.title+' · '+outcome,e.id);window._rp2OutreachModal=null;render()};
 window._rp2OutreachPushTask=function(eidEncoded,sidEncoded){var eid=decodeURIComponent(eidEncoded),sid=decodeURIComponent(sidEncoded),g=build(),e=g.enrollments.filter(function(x){return x.id===eid})[0];if(!e)return;var s=e.steps.filter(function(x){return x.id===sid&&x.status==='Open'})[0];if(!s)return;var ab=actions(),key='outreach:'+eid+':'+sid,dup=ab.data.manual.some(function(t){var st=ab.data.state[t.id]||{};return t&&t.sequenceStepKey===key&&st.status!=='completed'});if(!dup){var task={id:id('manual'),source:'manual',category:'outreach',tone:s.timeState==='Overdue'?'risk':'info',score:s.timeState==='Overdue'?190:165,title:s.step.title+' · '+(e.company||e.contactName||'Enrollment'),why:'Due sequence step in '+(e.campaign&&e.campaign.name||'campaign')+'.',action:s.step.instructions||('Complete the '+s.step.type+' step and record the actual result.'),measure:'Sequence step completed with an honest outcome.',dueDate:iso(s.dueAt||now()),customer:e.company,contactName:e.contactName,leadId:e.entityType==='lead'?e.entityKey:'',campaignId:e.campaignId,sequenceId:e.sequenceId,enrollmentId:e.id,sequenceStepId:s.id,sequenceStepKey:key,page:'outreach'};ab.data.manual.push(task);ab.data.events.push({type:'create',taskId:task.id,title:task.title,customer:e.company,campaignId:e.campaignId,at:new Date().toISOString()});saveActions(ab);audit('Outreach task created',task.title,fmt(s.dueAt),e.id)}render()};
 window._rp2OutreachPushToday=function(){var g=build();g.overdue.concat(g.today).forEach(function(s){window._rp2OutreachPushTask(encodeURIComponent(s.enrollmentId),encodeURIComponent(s.id))})};
 window._rp2OutreachApplyFilters=function(){try{var q=clean((document.getElementById('oc3-search')||{}).value).toLowerCase(),campaign=clean((document.getElementById('oc3-campaign-filter')||{}).value),status=clean((document.getElementById('oc3-status-filter')||{}).value),type=clean((document.getElementById('oc3-type-filter')||{}).value),cards=arr(document.querySelectorAll?document.querySelectorAll('#rp2-page [data-oc516="1"]'):[]),shown=0;cards.forEach(function(card){var ok=(!q||String(card.getAttribute('data-search')||'').indexOf(q)>=0)&&(!campaign||card.getAttribute('data-campaign')===campaign)&&(!status||card.getAttribute('data-status')===status)&&(!type||card.getAttribute('data-type')===type);card.style.display=ok?'grid':'none';if(ok)shown++});var count=document.getElementById('oc3-count');if(count)count.textContent=shown+' shown'}catch(e){}};
 window._rp2OutreachCopyPlan=function(){var g=build(),txt='OUTREACH CAMPAIGN PLAN — '+_rp2.rep+'\n\nActive campaigns: '+g.activeCampaigns.length+'\nActive enrollments: '+g.enrollments.filter(function(e){return e.status==='Active'}).length+'\nOverdue steps: '+g.overdue.length+'\nDue today: '+g.today.length+'\nCompleted steps: '+g.totalCompleted+'\nRecorded responses: '+g.responses.length+'\nMeetings scheduled: '+g.meetings.length+'\n\nPRIORITY STEPS\n';g.overdue.concat(g.today).concat(g.week).slice(0,12).forEach(function(s,i){txt+=(i+1)+'. '+s.step.title+' · '+(s.company||s.contactName||'Enrollment')+'\n   '+s.step.type+' · '+fmt(s.dueAt)+' · '+s.timeState+'\n   '+(s.step.instructions||'Complete and record the actual outcome.')+'\n\n'});try{if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(txt);else prompt('Copy outreach plan:',txt)}catch(e){prompt('Copy outreach plan:',txt)}};
 window._rp2OutreachV3=function(){try{var g=build(),tab=window._rp2OutreachTab,p=posture(g),active=g.enrollments.filter(function(e){return e.status==='Active'}).length;var hero='<div class="oc3-hero"><div class="oc3-hero-grid"><div><div class="oc3-kick">OUTREACH CAMPAIGNS & SALES SEQUENCES 3.0 · MANUAL EXECUTION SYSTEM · BUILD v516</div><div class="oc3-title">Build the cadence, execute the step, and record what actually happened</div><div class="oc3-copy">Create campaigns, clone or build sequences, enroll leads and CRM relationships, manage due-today work, record calls and emails honestly, capture real responses, update lead and contact activity, and measure execution without pretending the platform sent anything automatically.</div><div class="oc3-pills"><span class="oc3-pill '+p.tone+'">'+esc(p.title)+'</span><span class="oc3-pill info">'+g.activeCampaigns.length+' active campaigns</span><span class="oc3-pill">'+active+' active enrollments</span><span class="oc3-pill">Enrollment ≠ completed outreach</span></div><div class="oc3-actions"><button class="oc3-btn primary" onclick="_rp2OutreachNewCampaign()">＋ New campaign</button><button class="oc3-btn good" onclick="_rp2OutreachEnroll()">＋ Enroll audience</button><button class="oc3-btn blue" onclick="_rp2OutreachCopyPlan()">Copy outreach plan</button></div></div><div class="oc3-brief"><div><div class="oc3-brief-label">Manual execution completion</div><div class="oc3-brief-score">'+g.completionRate+'<span>%</span></div><div class="oc3-brief-title">'+g.overdue.length+' overdue · '+g.today.length+' due today · '+g.responses.length+' recorded responses</div><div class="oc3-brief-copy">Completion compares manually completed steps with planned steps. It does not represent delivery, opens, call connections, or customer intent unless recorded.</div></div><div class="oc3-brief-foot"><span>Response coverage <strong>'+g.responseRate+'%</strong></span><span>Meetings scheduled <strong>'+g.meetings.length+'</strong></span></div></div></div></div>';var kpis='<div class="oc3-kpis">'+kpi('Active campaigns',String(g.activeCampaigns.length),g.campaigns.length+' total campaigns')+kpi('Active enrollments',String(active),g.enrollments.length+' total enrollments')+kpi('Overdue steps',String(g.overdue.length),'Manual work past due')+kpi('Due today',String(g.today.length),g.week.length+' due next seven days')+kpi('Completed steps',String(g.totalCompleted),g.completionRate+'% of planned')+kpi('Recorded responses',String(g.responses.length),g.responseRate+'% coverage')+kpi('Positive responses',String(g.positive.length),g.meetings.length+' meetings')+kpi('Lead CRM conversions',String(g.converted.length),'Lead Center evidence')+'</div>';var content=tab==='campaigns'?campaignsView(g):tab==='sequences'?sequencesView(g):tab==='enrollments'?enrollmentsView(g):tab==='today'?todayView(g):tab==='responses'?responsesView(g):tab==='analytics'?analyticsView(g):tab==='history'?historyView(g):commandView(g);return'<div class="oc3-shell">'+hero+kpis+tabs(tab)+content+'</div>'+modalHtml(g)}catch(e){console.error('[Outreach v516 render error]',e);return'<div class="oc3-shell"><div class="oc3-hero"><div class="oc3-kick">OUTREACH CAMPAIGNS & SALES SEQUENCES 3.0 · RECOVERY MODE</div><div class="oc3-title">The outreach workspace hit a data compatibility issue</div><div class="oc3-copy">'+esc((e&&e.message)||String(e))+'</div></div></div>'}};
 window._rp2OutreachDraw=function(){if(typeof Chart!=='function'||['command','analytics','history'].indexOf(window._rp2OutreachTab)<0)return;var canvas=document.getElementById('oc3-chart');if(!canvas)return;var g=build();if(_rp2.outreachChart){try{_rp2.outreachChart.destroy()}catch(e){}}if(window._rp2OutreachTab==='command'){var r=g.campaignRows.filter(function(x){return x.metrics.enrolled>0}).slice(0,12);_rp2.outreachChart=new Chart(canvas.getContext('2d'),{type:'bar',data:{labels:r.map(function(x){return x.campaign.name}),datasets:[{label:'Completed steps',data:r.map(function(x){return x.metrics.completedSteps}),backgroundColor:'rgba(244,114,182,.68)',borderRadius:6},{label:'Planned steps',data:r.map(function(x){return x.metrics.steps}),backgroundColor:'rgba(0,175,239,.38)',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{labels:{color:'#aab4c6'}}}}})}else if(window._rp2OutreachTab==='analytics'){var r2=g.campaignRows.filter(function(x){return x.metrics.enrolled>0}).slice(0,15);_rp2.outreachChart=new Chart(canvas.getContext('2d'),{type:'bar',data:{labels:r2.map(function(x){return x.campaign.name}),datasets:[{label:'Step completion %',data:r2.map(function(x){return x.metrics.completionRate}),backgroundColor:'rgba(0,175,239,.65)',borderRadius:6},{label:'Response %',data:r2.map(function(x){return x.metrics.responseRate}),backgroundColor:'rgba(78,214,163,.62)',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{labels:{color:'#aab4c6'}}},scales:{y:{beginAtZero:true,max:100}}}})}else{var map={};arr(g.view.data.events).forEach(function(e){var d=stamp(e.at);if(d){var k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');map[k]=(map[k]||0)+1}});var total=0,rows=[];Object.keys(map).sort().forEach(function(k){total+=map[k];rows.push({label:k,value:total})});if(!rows.length)return;_rp2.outreachChart=new Chart(canvas.getContext('2d'),{type:'line',data:{labels:rows.map(function(x){return x.label}),datasets:[{label:'Cumulative outreach events',data:rows.map(function(x){return x.value}),borderColor:'#f472b6',backgroundColor:'rgba(244,114,182,.12)',fill:true,tension:.25}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}}}})}};
